-- VARI: pending database clean-up (run once in Supabase → SQL Editor).
-- Safe to run more than once.
begin;

-- 1) Remove the temporary function used only to seed the launch articles.
drop function if exists public.tmp_seed_blog_post(text, jsonb);

-- 2) Give the launch articles their real publish date (they were backdated).
--    Only touches posts whose publish date is earlier than the day they were created.
update public.blog_posts p
set publish_at = t.first_saved
from (
  select post_id, min(updated_at) as first_saved
  from public.blog_post_translations
  group by post_id
) t
where t.post_id = p.id
  and p.publish_at is not null
  and p.publish_at < p.created_at;

-- 3) Add the 4 SEO landing pages (skipped if a page with the same address exists).
insert into public.pages (slug, kind, title, seo, blocks, published, published_at, sort) values
($p$3d-rendering-services-for-developers$p$, 'custom', $p${"en":"3D rendering services for developers","de":"3D-Visualisierung für Bauträger","es":"Render 3D para promotoras"}$p$::jsonb, $p${"title":{"en":"3D Rendering Services for Real Estate Developers | VARI","de":"Visualisierung für Bauträger und Projektentwickler","es":"Render 3D para promotoras inmobiliarias | VARI"},"description":{"en":"Photorealistic 3D rendering services for real estate developers: exteriors, interiors, animations and virtual tours to sell off-plan, convince investors and win approvals.","de":"Fotorealistische 3D-Visualisierung für Bauträger: Außen- und Innenansichten, Animationen und virtuelle Rundgänge für Vertriebsstart, Investoren und Bauantrag.","es":"Render 3D fotorrealista para promotoras: exteriores, interiores, animaciones y tours virtuales para vender sobre plano, convencer a inversores y obtener licencias."},"image":"b80319_425c2f36f32b420da9c91cbd856c607d~mv2.jpg"}$p$::jsonb, $p$[{"id":"lp1ktceh","type":"hero","props":{"eyebrow":{"en":"For real estate developers","de":"Für Bauträger","es":"Para promotoras"},"title":{"en":"Sell your project *before* it is built","de":"Verkaufen Sie Ihr Projekt, *bevor* es gebaut ist","es":"Venda su promoción *antes* de construirla"},"subtitle":{"en":"Photorealistic exteriors, interiors, animations and virtual tours that carry your development from planning application to the last sale.","de":"Fotorealistische Außen- und Innenansichten, Animationen und virtuelle Rundgänge, die Ihr Projekt vom Bauantrag bis zum letzten Verkauf tragen.","es":"Exteriores, interiores, animaciones y tours virtuales fotorrealistas que acompañan su promoción desde la licencia hasta la última venta."},"image":"b80319_425c2f36f32b420da9c91cbd856c607d~mv2.jpg","buttons":[{"link":{"label":{"en":"Request a quote","de":"Angebot anfragen","es":"Pedir presupuesto"},"href":"/contact"}},{"link":{"label":{"en":"See our work","de":"Unsere Projekte","es":"Ver proyectos"},"href":"/work"}}],"height":"large","overlay":45,"align":"left"},"style":{}},{"id":"lp2ob5dm","type":"text","props":{"body":{"en":"## 3D rendering services built for developers\n\nBuyers, banks and planning authorities decide long before the first stone is laid. Our **3D rendering services for real estate developers** turn drawings into images people trust — consistent across your website, property portals, brochures, site hoarding and social media.\n\nWe build one detailed 3D model of your project and use it for every format you need, so later views, animations and tours build on work already done.","de":"## Visualisierung, die für Bauträger gemacht ist\n\nKäufer, Banken und Behörden entscheiden lange vor dem ersten Spatenstich. Unsere **Visualisierung für Bauträger** macht aus Plänen Bilder, denen man vertraut – einheitlich auf Website, Portalen, im Exposé, auf dem Bauschild und in Social Media.\n\nWir bauen ein detailliertes 3D-Modell Ihres Projekts und nutzen es für jedes Format, das Sie brauchen. So bauen spätere Ansichten, Animationen und Rundgänge auf vorhandener Arbeit auf.","es":"## Render 3D pensado para promotoras\n\nCompradores, bancos y administraciones deciden mucho antes de poner la primera piedra. Nuestro **render 3D para promotoras** convierte planos en imágenes creíbles, coherentes en su web, portales, folletos, valla de obra y redes sociales.\n\nConstruimos un modelo 3D detallado de su promoción y lo usamos para cada formato que necesite, de modo que las vistas, animaciones y tours posteriores parten del trabajo ya hecho."},"columns":"1","large":true},"style":{"width":"narrow"}},{"id":"lp32lvlg","type":"cards","props":{"eyebrow":{"en":"What we deliver","de":"Was wir liefern","es":"Qué entregamos"},"title":{"en":"One model, *every* channel","de":"Ein Modell, *alle* Kanäle","es":"Un modelo, *todos* los canales"},"items":[{"title":{"en":"Exterior renderings","de":"Außenvisualisierungen","es":"Renders de exteriores"},"body":{"en":"Hero views, street and garden perspectives, dusk scenes and aerials in context.","de":"Hauptansichten, Straßen- und Gartenperspektiven, Dämmerungsbilder und Luftbilder im Kontext.","es":"Vistas principales, perspectivas de calle y jardín, escenas al atardecer y vistas aéreas en su entorno."},"image":"8b4d4f_df3765a13fea45d5ba0da2dc00f8b694~mv2.png","link":{}},{"title":{"en":"Interior renderings","de":"Innenraumvisualisierungen","es":"Renders de interiores"},"body":{"en":"Show apartments furnished for your target buyer, with the specification they will receive.","de":"Wohnungen, eingerichtet für Ihre Zielgruppe – in der Ausstattung, die Käufer erhalten.","es":"Viviendas amuebladas para su comprador objetivo, con las calidades que recibirá."},"image":"b80319_962a6cc04617409f94ea031705d4ee66~mv2.png","link":{}},{"title":{"en":"Animation & virtual tours","de":"Animation & virtuelle Rundgänge","es":"Animación y tours virtuales"},"body":{"en":"Walk-throughs for launch events and immersive tours for buyers who cannot visit.","de":"Kamerafahrten für den Vertriebsstart und immersive Rundgänge für Käufer aus der Ferne.","es":"Recorridos para el lanzamiento y tours inmersivos para compradores que no pueden visitar."},"image":"8b4d4f_d8c978fb79044dd5b22cf9f8edca55b7~mv2.png","link":{}}],"columns":"3","numbered":true},"style":{}},{"id":"lp4b5ich","type":"projects","props":{"eyebrow":{},"title":{"en":"Selected *exteriors*","de":"Ausgewählte *Außenprojekte*","es":"Exteriores *seleccionados*"},"source":"exterior","slugs":[],"limit":3,"layout":"grid"},"style":{"width":"wide"}},{"id":"lp5esaca","type":"text","props":{"body":{"en":"## How a developer project runs with us\n\n1. **Brief and file check** — plans, elevations, materials and your target buyer.\n2. **Draft cameras** — we agree the views before detailed work starts.\n3. **Materials and light** — the stage that makes images believable.\n4. **Final images** — in the formats you need for print, portals and social media.\n5. **Next formats** — animation or a virtual tour from the same model.\n\nPlanning the budget? Read our [rendering cost guide](/blog/architectural-rendering-cost) and how to [use visuals to sell off-plan](/blog/3d-rendering-for-real-estate-developers).","de":"## So läuft ein Bauträgerprojekt mit uns\n\n1. **Briefing und Datenprüfung** – Pläne, Ansichten, Materialien und Ihre Zielgruppe.\n2. **Entwurfskameras** – wir stimmen die Ansichten ab, bevor die Detailarbeit beginnt.\n3. **Material und Licht** – die Phase, die Bilder glaubwürdig macht.\n4. **Finale Bilder** – in den Formaten für Druck, Portale und Social Media.\n5. **Weitere Formate** – Animation oder virtueller Rundgang aus demselben Modell.\n\nSie planen das Budget? Lesen Sie unseren Ratgeber zu den [Kosten einer Architekturvisualisierung](/blog/architekturvisualisierung-kosten) und wie Sie mit [Visualisierungen vor Baubeginn verkaufen](/blog/visualisierung-fuer-bautraeger).","es":"## Cómo trabajamos una promoción\n\n1. **Briefing y revisión de archivos**: planos, alzados, materiales y su comprador objetivo.\n2. **Cámaras en borrador**: acordamos las vistas antes del trabajo de detalle.\n3. **Materiales y luz**: la fase que hace creíbles las imágenes.\n4. **Imágenes finales**: en los formatos para impresión, portales y redes.\n5. **Siguientes formatos**: animación o tour virtual con el mismo modelo.\n\n¿Está preparando el presupuesto? Lea nuestra guía de [precios del render arquitectónico](/blog/precio-render-arquitectonico) y cómo [vender sobre plano con render inmobiliario](/blog/render-inmobiliario-para-promotoras)."},"columns":"1","large":false},"style":{"width":"narrow"}},{"id":"lp69rrf2","type":"faq","props":{"title":{"en":"Developer *questions*","de":"Fragen von *Bauträgern*","es":"Preguntas de *promotoras*"},"items":[{"q":{"en":"When should we order renderings?","de":"Wann sollten wir Visualisierungen beauftragen?","es":"¿Cuándo debemos encargar los renders?"},"a":{"en":"As soon as façades and layouts are stable — usually around the planning application — so the same images serve financing, approvals and the sales launch.","de":"Sobald Fassaden und Grundrisse stehen – meist rund um den Bauantrag –, damit dieselben Bilder für Finanzierung, Genehmigung und Vertriebsstart dienen.","es":"En cuanto fachadas y distribuciones estén cerradas, normalmente en torno a la licencia, para que las mismas imágenes sirvan para financiación, aprobaciones y lanzamiento."}},{"q":{"en":"Which files do you need?","de":"Welche Unterlagen brauchen Sie?","es":"¿Qué archivos necesitan?"},"a":{"en":"Plans, elevations and sections (DWG, RVT, SKP or PDF), a materials list and a few reference images. A 3D model speeds things up but is not required.","de":"Grundrisse, Ansichten und Schnitte (DWG, RVT, SKP oder PDF), eine Materialliste und einige Referenzbilder. Ein 3D-Modell beschleunigt, ist aber keine Voraussetzung.","es":"Plantas, alzados y secciones (DWG, RVT, SKP o PDF), una lista de materiales y algunas referencias. Un modelo 3D acelera el trabajo, pero no es imprescindible."}},{"q":{"en":"Can you work with our international team?","de":"Arbeiten Sie mit internationalen Teams?","es":"¿Pueden trabajar con nuestro equipo internacional?"},"a":{"en":"Yes. We work remotely with clients in Europe and North America, with clear milestones and online reviews.","de":"Ja. Wir arbeiten remote mit Kunden in Europa und Nordamerika – mit klaren Meilensteinen und Online-Abstimmungen.","es":"Sí. Trabajamos en remoto con clientes de Europa y Norteamérica, con hitos claros y revisiones online."}}]},"style":{"width":"narrow"}},{"id":"lp7fpnuw","type":"cta","props":{"title":{"en":"Tell us about your *development*","de":"Erzählen Sie uns von Ihrem *Projekt*","es":"Cuéntenos su *promoción*"},"body":{},"primary":{"label":{"en":"Request a quote","de":"Angebot anfragen","es":"Pedir presupuesto"},"href":"/contact"},"secondary":{"label":{"en":"See our work","de":"Unsere Projekte","es":"Ver proyectos"},"href":"/work"}},"style":{"bg":"charcoal","align":"center"}}]$p$::jsonb, true, now(), 200),
($p$interior-visualization-services$p$, 'custom', $p${"en":"Interior visualization services","de":"Innenraumvisualisierung","es":"Visualización de interiores"}$p$::jsonb, $p${"title":{"en":"Interior Rendering & Visualization Services | VARI Studio","de":"Innenraumvisualisierung – fotorealistische Renderings","es":"Render de interiores fotorrealista | VARI Studio"},"description":{"en":"Photorealistic interior rendering services for interior designers, developers and homeowners: living spaces, kitchens, bathrooms and commercial interiors.","de":"Fotorealistische Innenraumvisualisierung für Innenarchitekten, Bauträger und Bauherren: Wohnräume, Küchen, Bäder und gewerbliche Innenräume.","es":"Render de interiores fotorrealista para interioristas, promotoras y particulares: salones, cocinas, baños e interiores comerciales."},"image":"8b4d4f_ecc4d5d2e2734e05be4233cb2cb30abe~mv2.png"}$p$::jsonb, $p$[{"id":"lp8qzuga","type":"hero","props":{"eyebrow":{"en":"Interior visualization","de":"Innenraumvisualisierung","es":"Visualización de interiores"},"title":{"en":"Rooms you can *feel* before they exist","de":"Räume, die man *spürt*, bevor es sie gibt","es":"Espacios que se *sienten* antes de existir"},"subtitle":{"en":"Light, materials and mood rendered with the care of an interior photograph.","de":"Licht, Materialien und Stimmung – mit der Sorgfalt einer Interieurfotografie gerendert.","es":"Luz, materiales y ambiente renderizados con el cuidado de una fotografía de interiores."},"image":"8b4d4f_ecc4d5d2e2734e05be4233cb2cb30abe~mv2.png","buttons":[{"link":{"label":{"en":"Request a quote","de":"Angebot anfragen","es":"Pedir presupuesto"},"href":"/contact"}},{"link":{"label":{"en":"See our work","de":"Unsere Projekte","es":"Ver proyectos"},"href":"/work"}}],"height":"large","overlay":40,"align":"left"},"style":{}},{"id":"lp9cu2rq","type":"text","props":{"body":{"en":"## Interior rendering for every kind of space\n\nOur **interior rendering services** help interior designers win approval faster, developers show finished apartments while they are still a shell, and homeowners decide on materials before anything is ordered. We render living rooms, kitchens, bathrooms, bedrooms, offices, hospitality and retail interiors — and can also develop the interior concept itself.","de":"## Innenraumvisualisierung für jeden Raum\n\nUnsere **Innenraumvisualisierung** hilft Innenarchitekten, schneller Freigaben zu erhalten, Bauträgern, fertige Wohnungen im Rohbau zu zeigen, und Bauherren, Materialien vor der Bestellung zu entscheiden. Wir visualisieren Wohnräume, Küchen, Bäder, Schlafzimmer, Büros, Hotellerie und Läden – und entwickeln auf Wunsch auch das Innenraumkonzept selbst.","es":"## Render de interiores para cualquier espacio\n\nNuestro **render de interiores** ayuda a los interioristas a obtener aprobaciones antes, a las promotoras a mostrar viviendas terminadas cuando aún están en obra y a los particulares a decidir materiales antes de comprar. Renderizamos salones, cocinas, baños, dormitorios, oficinas, hostelería y comercios, y también podemos desarrollar el propio concepto de interiorismo."},"columns":"1","large":true},"style":{"width":"narrow"}},{"id":"lpa19evy","type":"gallery","props":{"images":["b80319_962a6cc04617409f94ea031705d4ee66~mv2.png","8b4d4f_1bfd140a3aec4e58898b8812dfebcdec~mv2.png","8b4d4f_2762a08d2c794d689b134249fc6cabac~mv2.png","8b4d4f_ecc4d5d2e2734e05be4233cb2cb30abe~mv2.png"],"layout":"masonry","columns":"2","lightbox":true},"style":{"width":"wide"}},{"id":"lpbd4882","type":"cards","props":{"eyebrow":{"en":"Who it is for","de":"Für wen","es":"Para quién"},"title":{"en":"Made for *decisions*","de":"Gemacht für *Entscheidungen*","es":"Pensado para *decidir*"},"items":[{"title":{"en":"Interior designers","de":"Innenarchitekten","es":"Interioristas"},"body":{"en":"Present concepts and material options that clients approve with confidence.","de":"Konzepte und Materialvarianten präsentieren, die Kunden sicher freigeben.","es":"Presente conceptos y opciones de materiales que el cliente aprueba con seguridad."},"image":"","link":{}},{"title":{"en":"Developers","de":"Bauträger","es":"Promotoras"},"body":{"en":"Show the finished apartment and amenities long before handover.","de":"Die fertige Wohnung und Gemeinschaftsflächen lange vor der Übergabe zeigen.","es":"Muestre la vivienda terminada y las zonas comunes mucho antes de la entrega."},"image":"","link":{}},{"title":{"en":"Homeowners","de":"Bauherren","es":"Particulares"},"body":{"en":"Compare layouts, colours and finishes before spending a cent.","de":"Grundrisse, Farben und Oberflächen vergleichen, bevor ein Cent ausgegeben ist.","es":"Compare distribuciones, colores y acabados antes de gastar un euro."},"image":"","link":{}}],"columns":"3","numbered":true},"style":{}},{"id":"lpclq5zo","type":"text","props":{"body":{"en":"## What to send us\n\n- Floor plan with dimensions and ceiling heights\n- Elevations of kitchens, built-ins and feature walls\n- Materials, finishes, furniture and lighting choices\n- Two or three reference images for the mood you want\n\nOur [interior rendering guide](/blog/interior-rendering-guide) explains the process step by step.","de":"## Was Sie uns schicken\n\n- Bemaßter Grundriss mit Raumhöhen\n- Ansichten von Küche, Einbauten und Gestaltungswänden\n- Materialien, Oberflächen, Möbel und Leuchten\n- Zwei bis drei Referenzbilder für die gewünschte Stimmung\n\nUnser [Ratgeber zur Innenraumvisualisierung](/blog/innenraumvisualisierung-ratgeber) erklärt den Ablauf Schritt für Schritt.","es":"## Qué enviarnos\n\n- Planta acotada con alturas de techo\n- Alzados de cocina, mobiliario a medida y paredes principales\n- Materiales, acabados, mobiliario e iluminación\n- Dos o tres referencias del ambiente que busca\n\nNuestra [guía de render de interiores](/blog/render-de-interiores-guia) explica el proceso paso a paso."},"columns":"1","large":false},"style":{"width":"narrow"}},{"id":"lpdr7odm","type":"projects","props":{"eyebrow":{},"title":{"en":"Interior *projects*","de":"Innenraum-*Projekte*","es":"Proyectos de *interiores*"},"source":"interior","slugs":[],"limit":6,"layout":"grid"},"style":{"width":"wide"}},{"id":"lpeqlv2i","type":"cta","props":{"title":{"en":"Let’s visualize your *interior*","de":"Visualisieren wir Ihren *Innenraum*","es":"Visualicemos su *interior*"},"body":{},"primary":{"label":{"en":"Request a quote","de":"Angebot anfragen","es":"Pedir presupuesto"},"href":"/contact"},"secondary":{"label":{"en":"See our work","de":"Unsere Projekte","es":"Ver proyectos"},"href":"/work"}},"style":{"bg":"charcoal","align":"center"}}]$p$::jsonb, true, now(), 200),
($p$architectural-visualization-germany$p$, 'custom', $p${"en":"Architectural visualization for Germany","de":"Architekturvisualisierung für Deutschland","es":"Visualización arquitectónica para Alemania"}$p$::jsonb, $p${"title":{"en":"Architectural Visualization for Projects in Germany | VARI","de":"Architekturvisualisierung für Projekte in Deutschland","es":"Visualización arquitectónica para Alemania | VARI"},"description":{"en":"Photorealistic architectural visualization for architects and developers in Germany — exteriors, interiors and animation, with remote collaboration and clear milestones.","de":"Fotorealistische Architekturvisualisierung für Architekten und Bauträger in Deutschland – Außen- und Innenansichten, Animationen, remote und mit klaren Meilensteinen.","es":"Visualización arquitectónica fotorrealista para arquitectos y promotoras en Alemania: exteriores, interiores y animación, con trabajo remoto e hitos claros."},"image":"8b4d4f_52780c64f74a4a3dac703141b59358c2~mv2.png"}$p$::jsonb, $p$[{"id":"lpff7urm","type":"hero","props":{"eyebrow":{"en":"Germany","de":"Deutschland","es":"Alemania"},"title":{"en":"Architectural visualization for *Germany*","de":"Architekturvisualisierung für *Deutschland*","es":"Visualización arquitectónica para *Alemania*"},"subtitle":{"en":"For architects, developers and housing companies who need precise, photorealistic images for competitions, planning and marketing.","de":"Für Architekten, Bauträger und Wohnungsunternehmen, die präzise, fotorealistische Bilder für Wettbewerb, Bauantrag und Vermarktung brauchen.","es":"Para arquitectos, promotoras y empresas de vivienda que necesitan imágenes precisas y fotorrealistas para concursos, licencias y marketing."},"image":"8b4d4f_52780c64f74a4a3dac703141b59358c2~mv2.png","buttons":[{"link":{"label":{"en":"Request a quote","de":"Angebot anfragen","es":"Pedir presupuesto"},"href":"/contact"}}],"height":"large","overlay":45,"align":"left"},"style":{}},{"id":"lpgg6tcu","type":"text","props":{"body":{"en":"## Precise architectural visualization for German projects\n\nGerman planning culture values precision: correct proportions, real materials and images that match the plans. Our **architectural visualization for Germany** is built on your drawings — Grundrisse, Ansichten and Schnitte — and on clear approval stages, so every image can stand in front of a planning committee, a jury or a buyer. One example is the [HNE Laboratory](/work/hne-laboratory) exterior for a project in Germany.\n\nWe work remotely with structured milestones: file check, draft cameras, materials and light, final images.","de":"## Präzise Architekturvisualisierung für Projekte in Deutschland\n\nDie deutsche Planungskultur schätzt Präzision: richtige Proportionen, echte Materialien und Bilder, die zu den Plänen passen. Unsere **Architekturvisualisierung für Deutschland** baut auf Ihren Unterlagen auf – Grundrisse, Ansichten und Schnitte – und auf klaren Freigabeschritten, damit jedes Bild vor Bauausschuss, Jury oder Käufer bestehen kann. Ein Beispiel ist die Außenvisualisierung des [HNE Laboratory](/work/hne-laboratory) für ein Projekt in Deutschland.\n\nWir arbeiten remote mit strukturierten Meilensteinen: Datenprüfung, Entwurfskameras, Material und Licht, finale Bilder.","es":"## Visualización arquitectónica precisa para proyectos en Alemania\n\nLa cultura de proyecto alemana valora la precisión: proporciones correctas, materiales reales e imágenes fieles a los planos. Nuestra **visualización arquitectónica para Alemania** parte de sus planos —plantas, alzados y secciones— y de fases de aprobación claras, para que cada imagen convenza a una comisión, un jurado o un comprador. Un ejemplo es el exterior del [HNE Laboratory](/work/hne-laboratory), un proyecto en Alemania.\n\nTrabajamos en remoto con hitos estructurados: revisión de archivos, cámaras en borrador, materiales y luz, imágenes finales."},"columns":"1","large":true},"style":{"width":"narrow"}},{"id":"lph2a8o0","type":"services","props":{"title":{"en":"Our *services*","de":"Unsere *Leistungen*","es":"Nuestros *servicios*"},"link":{"label":{"en":"All services","de":"Alle Leistungen","es":"Todos los servicios"},"href":"/services"}},"style":{}},{"id":"lpibjm8r","type":"faq","props":{"title":{"en":"Frequently asked *questions*","de":"Häufige *Fragen*","es":"Preguntas *frecuentes*"},"items":[{"q":{"en":"Do you work with German planning documents?","de":"Arbeiten Sie mit deutschen Planunterlagen?","es":"¿Trabajan con documentación de proyecto alemana?"},"a":{"en":"Yes — DWG, RVT, SKP or PDF plans, elevations and sections, as well as material schedules.","de":"Ja – mit Grundrissen, Ansichten und Schnitten als DWG, RVT, SKP oder PDF sowie mit Material- und Ausstattungslisten.","es":"Sí: plantas, alzados y secciones en DWG, RVT, SKP o PDF, además de listas de materiales."}},{"q":{"en":"What does a visualization cost?","de":"Was kostet eine Visualisierung?","es":"¿Cuánto cuesta una visualización?"},"a":{"en":"Each project is quoted individually after we see the drawings. Our cost guide explains typical market ranges in Germany.","de":"Jedes Projekt wird nach Sichtung der Pläne individuell kalkuliert. Übliche Preisspannen in Deutschland erklärt unser Ratgeber „Was kostet eine Architekturvisualisierung?“.","es":"Cada proyecto se presupuesta tras ver los planos. Nuestra guía de precios explica los rangos habituales."}}]},"style":{"width":"narrow"}},{"id":"lpjey6k3","type":"cta","props":{"title":{"en":"Start your project in *Germany*","de":"Starten Sie Ihr Projekt mit *uns*","es":"Empiece su proyecto en *Alemania*"},"body":{},"primary":{"label":{"en":"Request a quote","de":"Angebot anfragen","es":"Pedir presupuesto"},"href":"/contact"},"secondary":{"label":{"en":"See our work","de":"Unsere Projekte","es":"Ver proyectos"},"href":"/work"}},"style":{"bg":"charcoal","align":"center"}}]$p$::jsonb, true, now(), 200),
($p$architectural-rendering-spain$p$, 'custom', $p${"en":"Architectural rendering for Spain","de":"Architekturvisualisierung für Spanien","es":"Render arquitectónico para España"}$p$::jsonb, $p${"title":{"en":"Architectural Rendering for Projects in Spain | VARI Studio","de":"Architekturvisualisierung für Projekte in Spanien","es":"Render arquitectónico para proyectos en España | VARI"},"description":{"en":"Photorealistic architectural rendering for developers, architects and interior designers in Spain: exteriors, interiors, animation and virtual tours.","de":"Fotorealistische Architekturvisualisierung für Bauträger, Architekten und Innenarchitekten in Spanien: Außen- und Innenansichten, Animationen und Rundgänge.","es":"Render arquitectónico fotorrealista para promotoras, arquitectos e interioristas en España: exteriores, interiores, animación y tours virtuales."},"image":"8b4d4f_525775bc11554914a009fed0206e2afc~mv2.png"}$p$::jsonb, $p$[{"id":"lpkhp91q","type":"hero","props":{"eyebrow":{"en":"Spain","de":"Spanien","es":"España"},"title":{"en":"Architectural rendering for *Spain*","de":"Architekturvisualisierung für *Spanien*","es":"Render arquitectónico para *España*"},"subtitle":{"en":"Photorealistic visuals for off-plan sales, coastal villas, urban apartments and interior design projects — with project communication in Spanish.","de":"Fotorealistische Bilder für den Vorabverkauf, Küstenvillen, Stadtwohnungen und Innenarchitektur – mit Projektkommunikation auf Spanisch.","es":"Imágenes fotorrealistas para venta sobre plano, villas de costa, viviendas urbanas y proyectos de interiorismo, con comunicación en español."},"image":"8b4d4f_525775bc11554914a009fed0206e2afc~mv2.png","buttons":[{"link":{"label":{"en":"Request a quote","de":"Angebot anfragen","es":"Pedir presupuesto"},"href":"/contact"}}],"height":"large","overlay":45,"align":"left"},"style":{}},{"id":"lplbsmx5","type":"text","props":{"body":{"en":"## Architectural rendering for promotions in Spain\n\nOff-plan sales are central to new residential development in Spain, and buyers — local and international — decide from images. Our **architectural rendering for Spain** covers exteriors in natural light, furnished interiors with the specification buyers receive, amenities such as pools and gardens, and animations or virtual tours for buyers who cannot visit.\n\nWe work remotely, with milestones and reviews online. Planning your budget? See our guide to [rendering cost](/blog/architectural-rendering-cost).","de":"## Visualisierung für Bauprojekte in Spanien\n\nDer Vorabverkauf ist im spanischen Wohnungsneubau zentral, und Käufer – lokal wie international – entscheiden anhand von Bildern. Unsere **Architekturvisualisierung für Spanien** umfasst Außenansichten im natürlichen Licht, möblierte Innenräume in der tatsächlichen Ausstattung, Gemeinschaftsflächen wie Pools und Gärten sowie Animationen oder Rundgänge für Käufer aus der Ferne.\n\nWir arbeiten remote, mit Meilensteinen und Online-Abstimmung. Zum Budget hilft unser Ratgeber [Was kostet eine Architekturvisualisierung?](/blog/architekturvisualisierung-kosten)","es":"## Render arquitectónico para promociones en España\n\nLa venta sobre plano es clave en la obra nueva residencial en España, y los compradores —nacionales e internacionales— deciden a partir de imágenes. Nuestro **render arquitectónico para España** incluye exteriores con luz natural, interiores amueblados con las calidades reales, zonas comunes como piscinas y jardines, y animaciones o tours virtuales para compradores que no pueden visitar.\n\nTrabajamos en remoto, con hitos y revisiones online. ¿Preparando el presupuesto? Consulte nuestra guía [¿Cuánto cuesta un render arquitectónico?](/blog/precio-render-arquitectonico)"},"columns":"1","large":true},"style":{"width":"narrow"}},{"id":"lpm1qkoa","type":"projects","props":{"eyebrow":{},"title":{"en":"Selected *work*","de":"Ausgewählte *Projekte*","es":"Proyectos *seleccionados*"},"source":"featured","slugs":[],"limit":3,"layout":"grid"},"style":{"width":"wide"}},{"id":"lpnletih","type":"faq","props":{"title":{"en":"Frequently asked *questions*","de":"Häufige *Fragen*","es":"Preguntas *frecuentes*"},"items":[{"q":{"en":"Can we work in Spanish?","de":"Ist die Zusammenarbeit auf Spanisch möglich?","es":"¿Podemos trabajar en español?"},"a":{"en":"Yes — the website, our communication and the project reviews are available in Spanish, English and German.","de":"Ja – Website, Kommunikation und Projektabstimmungen sind auf Spanisch, Englisch und Deutsch möglich.","es":"Sí: la web, la comunicación y las revisiones del proyecto están disponibles en español, inglés y alemán."}},{"q":{"en":"Which format suits an off-plan launch?","de":"Welches Format passt zum Vertriebsstart?","es":"¿Qué formato encaja con un lanzamiento sobre plano?"},"a":{"en":"Usually a set of still renderings first, then an animation for the launch and a virtual tour for remote buyers.","de":"Meist zuerst eine Serie Standbilder, dann eine Animation zum Start und ein virtueller Rundgang für Käufer aus der Ferne.","es":"Normalmente primero una serie de renders, después una animación para el lanzamiento y un tour virtual para compradores a distancia."}}]},"style":{"width":"narrow"}},{"id":"lpo3qezz","type":"cta","props":{"title":{"en":"Plan the visuals for your *project*","de":"Planen Sie Ihre *Visualisierungen*","es":"Planifique los renders de su *proyecto*"},"body":{},"primary":{"label":{"en":"Request a quote","de":"Angebot anfragen","es":"Pedir presupuesto"},"href":"/contact"},"secondary":{"label":{"en":"See our work","de":"Unsere Projekte","es":"Ver proyectos"},"href":"/work"}},"style":{"bg":"charcoal","align":"center"}}]$p$::jsonb, true, now(), 200)
